// portraits des héros Ninja fournis par l'utilisateur (classique + éveil), recadrés sur le visage
const HIMG = {
  nh_naruto:'data:image/jpeg;base64,',
  nh_naruto_aw:'data:image/jpeg;base64,',
  nh_kankuro:'data:image/jpeg;base64,',
  nh_kankuro_aw:'data:image/jpeg;base64,',
  nh_kushina:'data:image/jpeg;base64,',
  nh_kushina_aw:'data:image/jpeg;base64,',
  nh_hashirama:'data:image/jpeg;base64,',
  nh_hashirama_aw:'data:image/jpeg;base64,',
  nh_jiraiya:'data:image/jpeg;base64,',
  nh_jiraiya_aw:'data:image/jpeg;base64,',
  nh_kakashi:'data:image/jpeg;base64,',
  nh_kakashi_aw:'data:image/jpeg;base64,',
  nh_deidara:'data:image/jpeg;base64,',
  nh_deidara_aw:'data:image/jpeg;base64,',
  nh_sasori:'data:image/jpeg;base64,',
  nh_sasori_aw:'data:image/jpeg;base64,',
  nh_rasa:'data:image/jpeg;base64,',
  nh_rasa_aw:'data:image/jpeg;base64,',
  nh_kakuzu:'data:image/jpeg;base64,',
  nh_kakuzu_aw:'data:image/jpeg;base64,',
  nh_itachi:'data:image/jpeg;base64,',
  nh_itachi_aw:'data:image/jpeg;base64,',
  nh_yugito:'data:image/jpeg;base64,',
  nh_yugito_aw:'data:image/jpeg;base64,',
  nh_gaara:'data:image/jpeg;base64,',
  nh_gaara_aw:'data:image/jpeg;base64,',
  nh_bee:'data:image/jpeg;base64,',
  nh_bee_aw:'data:image/jpeg;base64,',
  nh_shikamaru:'data:image/jpeg;base64,',
  nh_shikamaru_aw:'data:image/jpeg;base64,',
  nh_roshi:'data:image/jpeg;base64,',
  nh_roshi_aw:'data:image/jpeg;base64,',
  nh_sasuke:'data:image/jpeg;base64,',
  nh_sasuke_aw:'data:image/jpeg;base64,',
  nh_omoi:'data:image/jpeg;base64,',
  nh_omoi_aw:'data:image/jpeg;base64,',
  nh_haku:'data:image/jpeg;base64,',
  nh_haku_aw:'data:image/jpeg;base64,',
  nh_mei:'data:image/jpeg;base64,',
};
for (const id in HIMG) HART[id] = () => `<rect width="100" height="100" fill="#1a120c"/><image href="${HIMG[id]}" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid slice" style="image-rendering:auto"/>`;
// portrait du héros : version éveillée si elle existe
const heroArt = (h, aw) => 'art-h-' + h + (aw && HART[h + '_aw'] ? '_aw' : '');
// invocations (animaux de pacte) : images fournies par l'utilisateur
const TIMG = {
  tk_toad:'data:image/jpeg;base64,',
  tk_slug:'data:image/jpeg;base64,',
  tk_snake:'data:image/jpeg;base64,',
  tk_shark:'data:image/jpeg;base64,',
};
for (const id in TIMG) ART[id] = () => `<image href="${TIMG[id]}" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid slice"/>`;
